Here is the root cause:
The bug arises from the default behavior of the generic netlink framework, which allows non-root users to listen to notifications from the "events" multicast group of the NET_DM family. This poses a security risk as sensitive information about drop locations can be accessed by unauthorized users. The solution involves requiring the `CAP_SYS_ADMIN` capability for joining this multicast group to restrict access to privileged users only.

Here is the patch:

 static int genl_bind(struct net *net, int group)
 {
 	const struct genl_family *family;
 	unsigned int id;
 	int ret = 0;

 	down_read(&cb_lock);

 	idr_for_each_entry(&genl_fam_idr, family, id) {
 		const struct genl_multicast_group *grp;
 		int i;

 		if (family->n_mcgrps == 0)
 			continue;

 		i = group - family->mcgrp_offset;
 		if (i < 0 || i >= family->n_mcgrps)
 			continue;

 		grp = &family->mcgrps[i];
 		if ((grp->flags & GENL_UNS_ADMIN_PERM) &&
 		    !ns_capable(net->user_ns, CAP_NET_ADMIN))
 			ret = -EPERM;
+		if (grp->cap_sys_admin &&
+		    !ns_capable(net->user_ns, CAP_SYS_ADMIN))
+			ret = -EPERM;

 		break;
 	}

 	up_read(&cb_lock);
 	return ret;
 }



